// and the movements on or before ends_on of a payment whose period ends on or after starts_on,
// with the period of their payment.
func (q *Queries) ListIncomeMovementsInWindow(ctx context.Context, arg ListIncomeMovementsInWindowParams) ([]ListIncomeMovementsInWindowRow, error) {
	rows, err := q.db.Query(ctx, listIncomeMovementsInWindow, arg.StartsOn, arg.EndsOn)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListIncomeMovementsInWindowRow{}
	for rows.Next() {
		var i ListIncomeMovementsInWindowRow
		if err := rows.Scan(
			&i.Kind,
			&i.OccurredOn,
			&i.CoversStartsOn,
			&i.CoversEndsOn,
			&i.GrossMinor,
			&i.FeeMinor,
			&i.NetMinor,
			&i.Currency,
			&i.ParentCoversStartsOn,
			&i.ParentCoversEndsOn,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockBillingImportSource = `-- name: LockBillingImportSource :exec
SELECT pg_advisory_xact_lock(hashtextextended($1::text, 0))
`

// LockBillingImportSource takes a transaction-scoped advisory lock on the imports of a source, so
// that attempts reserve requests one at a time.
func (q *Queries) LockBillingImportSource(ctx context.Context, lockKey string) error {
	_, err := q.db.Exec(ctx, lockBillingImportSource, lockKey)
	return err
}

const lockImportedCostHeads = `-- name: LockImportedCostHeads :exec
SELECT 1 FROM imported_cost_heads
WHERE source = $1 AND billing_month = ANY($2::text[])
FOR UPDATE
`

type LockImportedCostHeadsParams struct {
	Source string
	Months []string
}

// LockImportedCostHeads locks the heads of a source's billing months, so that two imports of
// the source compare and write one after the other.
func (q *Queries) LockImportedCostHeads(ctx context.Context, arg LockImportedCostHeadsParams) error {
	_, err := q.db.Exec(ctx, lockImportedCostHeads, arg.Source, arg.Months)
	return err
}

const pendingBillingImportReservation = `-- name: PendingBillingImportReservation :one
SELECT EXISTS (
  SELECT 1 FROM billing_import_reservations r
  WHERE r.source = $1 AND r.reserved_at >= $2
    AND NOT EXISTS (SELECT 1 FROM billing_import_runs u WHERE u.id = r.id)
) AS pending
`

type PendingBillingImportReservationParams struct {
	Source string
	Since  time.Time
}

// PendingBillingImportReservation reports whether an attempt of a source reserved requests at or
// after since and is not recorded yet: it is still running.
func (q *Queries) PendingBillingImportReservation(ctx context.Context, arg PendingBillingImportReservationParams) (bool, error) {
	row := q.db.QueryRow(ctx, pendingBillingImportReservation, arg.Source, arg.Since)
	var pending bool
	err := row.Scan(&pending)
	return pending, err
}

const sumBillingImportRuns = `-- name: SumBillingImportRuns :one
SELECT COALESCE(SUM(requests), 0)::bigint AS requests, COALESCE(SUM(bytes_billed), 0)::bigint AS bytes_billed
FROM (
  SELECT u.requests, u.bytes_billed FROM billing_import_runs u
  WHERE u.source = $1 AND u.occurred_at >= $2 AND u.occurred_at < $3
  UNION ALL
  SELECT r.requests, 0 FROM billing_import_reservations r
  WHERE r.source = $1 AND r.reserved_at >= $2 AND r.reserved_at < $3
    AND NOT EXISTS (SELECT 1 FROM billing_import_runs u WHERE u.id = r.id)
) AS usage
`

type SumBillingImportRunsParams struct {
	Source  string
	FromAt  time.Time
	UntilAt time.Time
}

type SumBillingImportRunsRow struct {
	Requests    int64
	BytesBilled int64
}

// SumBillingImportRuns sums the requests and the bytes billed of the attempts of a source that
// occurred in [from, until), counting the reservation of an attempt that is not recorded yet in
// place of its requests.
func (q *Queries) SumBillingImportRuns(ctx context.Context, arg SumBillingImportRunsParams) (SumBillingImportRunsRow, error) {
	row := q.db.QueryRow(ctx, sumBillingImportRuns, arg.Source, arg.FromAt, arg.UntilAt)
	var i SumBillingImportRunsRow
	err := row.Scan(&i.Requests, &i.BytesBilled)
	return i, err
}

const upsertCostItemHead = `-- name: UpsertCostItemHead :exec
INSERT INTO cost_item_heads (cost_item_id, label_revision_id, ends_on) VALUES ($1, $2, $3)
ON CONFLICT (cost_item_id) DO UPDATE SET label_revision_id = excluded.label_revision_id, ends_on = excluded.ends_on
`

type UpsertCostItemHeadParams struct {
	CostItemID      string
	LabelRevisionID string
	EndsOn          pgtype.Date
}

func (q *Queries) UpsertCostItemHead(ctx context.Context, arg UpsertCostItemHeadParams) error {
	_, err := q.db.Exec(ctx, upsertCostItemHead, arg.CostItemID, arg.LabelRevisionID, arg.EndsOn)
	return err
}

const upsertImportedCostHead = `-- name: UpsertImportedCostHead :exec
INSERT INTO imported_cost_heads (source, billing_month, service, charge_type, revision_id) VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (source, billing_month, service, charge_type) DO UPDATE SET revision_id = excluded.revision_id
`

type UpsertImportedCostHeadParams struct {
	Source       string
	BillingMonth string
	Service      string
	ChargeType   string
	RevisionID   string
}

func (q *Queries) UpsertImportedCostHead(ctx context.Context, arg UpsertImportedCostHeadParams) error {
	_, err := q.db.Exec(ctx, upsertImportedCostHead,
		arg.Source,
		arg.BillingMonth,
		arg.Service,
		arg.ChargeType,
		arg.RevisionID,
	)
	return err
}
